// # HELPER FUNCTIONS FOR VOCAB
// See # VOCAB LIST to manage vocabulary data
//
// # OPTIONS
// -----------
// ## Supported Prefixes in Strings
// K - forces usage of kanji if available
// H - forces usage of Hiragana/Katakana only; no kanji is displayed
// -----------
// ## Supported Suffixes in Strings
// M[MEANING_INDEXES] - limits meanings displayed for a word to those selected
// EXAMPLE: M[0,1,3] only displays the first, second, and fourth meanings for a word, whereas M[0] would only display the first meaning
// -----------
// ## Example Usage and Syntax
/*
  Kantan.vocabQuizlet([
    'Kいってきます', // prefixing with K forces usage of Kanji variant when available
    'いってらっしゃいM[0,1,3]', // only include meanings 0, 1, & 3 (can only be used at end of string)
    'ただいま',
    'おかえり',
    'Hおかえりなさい', // prefixing with H forces usage of Hiragana/Katakana variant; no kanji whatsoever
    'いただきます',
    'ごちそうさま',
    'ごちそうさまでした',
    'はじめまして',
    '～です',
    'よろしく',
    'よろしくおねがいします'
  ]{
   forceKanji : true, // forces kanji for ALL entries passed to vocab; kana is displayed as furigana
   forceKana : true, // forces Hiragana/Katakana for ALL entries passed to vocab; kanji is NOT displayed
   maxMeanings : 3, // limits the number of meanings shown for all words to 3
   swapExamples : true // swaps the position of the Japanese and English example sentences (false: JA --> EN (default); true: EN --> JA)
  })
*/
// returns object for use in vocab exercises' quizlet
Kantan.vocabQuizlet = function (vocab, settings) {
  settings = settings || {};
  if (settings.limitMeanings) settings.maxMeanings = settings.limitMeanings; // port over legacy setting
  vocab = vocab || [];
  Kantan.vocabCache = vocab; // for use in kantan.js when special settings need to be applied, such as for the written vocab exercises
  
  if (settings.maxMeanings <= 0) settings.maxMeanings = 1; // prevents no meanings from being shown
  
  var o = {}, i = 0, j = vocab.length, k, l, vocabKey, word, meaning, meaningList, limitedMeanings, kanji, kana, cleanWord;
  
  // generate quizlet
  for (; i < j; i++) {
    vocabKey = vocab[i].replace(/^K|^H|M\[.*?\]$/g, ''); // clean vocab string
    
    if (Kantan.vocab[vocabKey]) {
      // check for flags
      kanji = vocab[i].charAt(0) == 'K' || settings.forceKanji;
      kana = vocab[i].charAt(0) == 'H' || settings.forceKana;
      limitedMeanings = vocab[i].match(/M\[(.*?)\]$/);
      // clean vocab and grab word/meaning from vocab object
      word = Kantan.vocab[vocabKey];
      meaning = word.meaning;

      // limits the amount of meanings shown for a word
      if (settings.maxMeanings != undefined || limitedMeanings) {
        meaningList = meaning.split(';');
        limitedMeanings = limitedMeanings && limitedMeanings[1] ? limitedMeanings[1].split(',') : null;

        for (k = 0, l = limitedMeanings ? limitedMeanings.length : settings.maxMeanings, meaning = ''; k < l; k++) {
          if (limitedMeanings) {
            meaning += meaningList[limitedMeanings[k].replace(/\s+/g, '')] + ';';
          } else if (meaningList[k]) {
            meaning += meaningList[k] + ';';
          }
        }

        // slice off last ;
        meaning = meaning.slice(0, -1); 
      }

      // format vocab object
      if (word) {
        cleanWord = Kantan.cleanVocabKey(vocabKey);
        
        // kanji|kana
        o[((!kana && (word.kanji && (!word.often_kana || kanji))) ? word.kanji + '|' : '') + cleanWord] = 
          // definition + color code keywords
          Kantan.highlightKeywords(meaning)+
          // first example sentence (default is Japanese)
          (word.example_ja || word.example_en ? '|' : '') + (word['example_' + ( settings.swapExamples ? 'en' : 'ja' )] ? '<div class="multi-vocab-sentence-' + ( settings.swapExamples ? 'en' : 'ja' ) + '">' + word['example_' + ( settings.swapExamples ? 'en' : 'ja' )] + '</div>' : '')+
          // second example sentence (default is English)
          (word['example_' + ( settings.swapExamples ? 'ja' : 'en' )] ? '<div class="multi-vocab-sentence-' + ( settings.swapExamples ? 'ja' : 'en' ) + '">' + word['example_' + ( settings.swapExamples ? 'ja' : 'en' )] + '</div>' : '');
      }
      
    } else {
      console.error('vocabQuizlet ERROR: "' + vocab[i] + '" cannot be found in vocab.js. Please verify that this word is available in vocab.js or check for any typos in this entry.');
    }
  }
  
  return o;
};


// shows example sentences in a popup window
Kantan.viewExample = function (word, caller) {
  var data = Kantan.vocab[word], answered, cleanWord;
  
  if (data) {
    // only shows the english examples when: answered, in review mode, or during writing quizzes
    answered = caller ? (caller.parentNode.parentNode.querySelector('.answer-correct') || document.querySelector('.review-mode, .writing-quiz')) : true;
    cleanWord = Kantan.cleanVocabKey(word);
    
    // open popup with example sentences
    KantanModal.open({
      title : '<span class="en">Example Sentence</span><span class="ja">例文</span>',
      content :
        '<div class="quiz-multi-question quick-example" style="border-bottom:none;">'+
          '<div class="multi-vocab">'+
            (data.kanji && !data.often_kana ? '<ruby>' + data.kanji + '<rt>' + (data.readings || cleanWord) + '</rt></ruby>' : cleanWord)+
            Kantan.create.vocabAudio(word)+
            '<div class="multi-vocab-tags">' + Kantan.parse.vocabTags(word) + '</div>'+
            '<div class="multi-vocab-sentence" style="display:block !important;"><hr>'+
              (data.example_ja ? '<div class="multi-vocab-sentence-ja">' + data.example_ja + '</div>' : '')+
              (answered && data.example_en ? '<div class="multi-vocab-sentence-en">' + data.example_en + '</div>' : '')+
            '</div>'+
          '</div>'+
        '</div>',

      customSize : {
        top : '5%',
        left : '10%',
        right : '10%',
        bottom : '10%'
      }
    });
  }
};


// highlights keywords in meanings
Kantan.highlightKeywords = function (str) {
  return str.replace(/(\[(?:|casual|polite|humble|modest|honorific|formal)\])/gi, '<b class="main-color">$1</b>');
};


// pass a tag along to return its color for use in the class="" attribute
Kantan.vocabTagColor = function (tag) {
  return (tag == 'Exp' || tag == 'Phr') ? 'yellow' :
         tag == 'Conj' ? 'light-yellow' :
         tag == 'Abbr' ? 'green' :
         (tag == 'Pre' || tag == 'Suf') ? 'dark-green' :
         (tag == 'A' || tag == 'ANa' || tag == 'ANo') ? 'pink' :
         (tag == 'Pol' || tag == 'Hum' || tag == 'Hon') ? 'blue' :
         (tag == 'N' || tag == 'PN' || tag == 'VN') ? 'red' :
         tag == 'Int' ? 'light-red' :
         tag == 'Adv' ? 'orange' :
         tag == 'Irr' ? 'gray' : '';
};


// Parses vocabulary tags for dictionary definitions
Kantan.parse.vocabTags = function (word, opts) {
  if (!opts) opts = {};
  
  word = Kantan.vocab[word];
  var tags = '';
  
  if (word && !opts.plain) {
    // parse list of tags
    for (var tagList = word.tag.replace(/\s/g, '').split(','), i = 0, j = tagList.length; i < j; i++) {
      tags += '<span class="def-tag ' + Kantan.vocabTagColor(tagList[i]) + '" title="' + Kantan.vocabTagKey[tagList[i]] + '" onclick="Kantan.viewVocabTags();">' + tagList[i] + '</span>';
    }
    // additional tags
    if (word.often_kana) tags += '<span class="def-tag purple" title="Usually written using kana instead of kanji" onclick="Kantan.viewVocabTags();">Kana</span>';
    if (word.jlpt) tags += '<span class="def-tag light-blue" title="JLPT Level" onclick="Kantan.viewVocabTags();">N' + word.jlpt + '</span>';
    
    // textbook tags
    if (!opts.excludeTextbooks) {
      if (typeof word.genki == 'number') tags += '<span class="def-tag orange" title="Appears in the Genki textbook series" onclick="Kantan.viewVocabTags();">Genki L' + word.genki + '</span>';
      if (typeof word.tobira_b == 'number') tags += '<span class="def-tag light-blue" title="Appears in the Tobira Beginning Japanese textbook series" onclick="Kantan.viewVocabTags();">Tobira-B L' + word.tobira_b + '</span>';
      if (typeof word.tobira_i == 'number') tags += '<span class="def-tag blue" title="Appears in the Tobira Intermediate textbook series" onclick="Kantan.viewVocabTags();">Tobira-I L' + word.tobira_i + '</span>';
      if (typeof word.quartet == 'number') tags += '<span class="def-tag pink" title="Appears in the Quartet textbook series" onclick="Kantan.viewVocabTags();">Quartet L' + word.quartet + '</span>';
    }
  }
  
  // plain parsed tag list
  else if (word && opts.plain) {
    for (var tagList = word.tag.replace(/\s/g, '').split(','), i = 0, j = tagList.length; i < j; i++) {
      tags += Kantan.vocabTagKey[tagList[i]].replace(/;.*?$|\s\(.*?\)/, '') + ', ';
    }
  }
  
  return (opts.plain ? tags.replace(/, $/, '') : tags);
};


// shows extended information on all of the vocabulary tags
Kantan.viewVocabTags = function () {
  var list = '', k;
  
  for (k in Kantan.vocabTagKey) {
    list += '<tr><td class="tag-cell"><span class="def-tag '+ Kantan.vocabTagColor(k) + '" style="cursor:default;">' + k + '</span></td><td class="tag-desc-cell">' + Kantan.vocabTagKey[k] + '</td></tr>';
  }
  list += 
    '<tr><td class="tag-cell"><span class="def-tag purple">Kana</span></td><td class="tag-desc-cell">Words with this tag are usually written entirely in hiragana or katakana rather than kanji.</td></tr>'+
    '<tr><td class="tag-cell"><span class="def-tag light-blue">N5</span></td><td class="tag-desc-cell">Estimated JLPT Level of a word (from <a href="https://www.tanos.co.uk/jlpt/" target="_blank">JLPT Resources</a>). JLPT level ranges from N5 (easiest) to N1 (hardest).</td></tr>'+
    '<tr><td class="tag-cell"><span class="def-tag orange">Genki</span></td><td class="tag-desc-cell">Word that appears in the Genki textbook series.</td></tr>'+
    '<tr><td class="tag-cell"><span class="def-tag light-blue">Tobira-B</span></td><td class="tag-desc-cell">Word that appears in the Tobira Beginning Japanese textbook series.</td></tr>'+
    '<tr><td class="tag-cell"><span class="def-tag blue">Tobira-I</span></td><td class="tag-desc-cell">Word that appears in the Tobira Intermediate textbook series.</td></tr>'+
    '<tr><td class="tag-cell"><span class="def-tag pink">Quartet</span></td><td class="tag-desc-cell">Word that appears in the Quartet textbook series.</td></tr>';
  
  
  KantanModal.open({
    title : '<span class="en">Vocabulary Tag Meanings</span><span class="ja">単語のタグの意味</span>',
    content : '<p>Vocabulary Tags provide additional information for words, such as indicating what part of speech a word belongs to, if it is only written in kana, etc.</p>'+
              '<table class="table vocab-tag-legend">'+
              '<tr class="table-head"><td class="center"><span class="en">Tag</span><span class="ja">タッグ</span></td><td><span class="en">Meaning</span><span class="ja">意味</span></td></tr>'+
              list+
              '</table><br>',
    
    customSize : {
      top : '5%',
      left : '20%',
      right : '20%',
      bottom : '10%'
    }
  });
};


// returns audio and controls formatted for vocabulary exercises
// word = string or array ['word-1', 'word-2'] // array searches for audio in multiple entries until it finds a file
// empty returns a disabled style button
Kantan.create.vocabAudio = function (word, empty) {
  if (word && Kantan.vocab) {
    if (typeof word == 'string') word = [word];
    
    var str = '', i = 0, j = word.length;

    for (; i < j; i++) {
      if (Kantan.vocab[word[i]] && Kantan.vocab[word[i]].audio) {
        str = '<audio id="' + word[i] + '" class="vocab-audio" style="display:none;" controls>'+
          '<source src="' + getPaths() + 'resources/audio/vocab/mp3/' + Kantan.vocab[word[i]].audio + '.mp3" type="audio/mpeg">'+
          '<source src="' + getPaths() + 'resources/audio/vocab/ogg/' + Kantan.vocab[word[i]].audio + '.ogg" type="audio/ogg">'+
        '</audio>'+
        '<button class="button icon-only round audio" onclick="Kantan.playAudio(\'' + word[i] + '\');" title="' + (KN_Lang == 'en' ? 'Play audio' : '音声を聞く') + '"><i class="fa"></i></button>';
        break; // break out of loop if audio file is found
      }
    }
    
    // disabled button if no audio found
    if (str == '' && empty) {
      str = '<button class="button icon-only round audio opt-off disabled" title="Sorry, audio is currently unavailable for this entry."><i class="fa"></i></button>';
    }

    return str;
  }

  else {
    return '';
  }
};

// returns a button that opens an example sentence in a popup window
// "drag" (bool) applies special values for drag and drop exercises
Kantan.create.vocabExample = function (word, drag) {
  var str = '';
  
  if (Kantan.vocab[word]) {
    str = '<button class="button icon-only round reibun' + (drag ? ' view-example' : '') + '" title="' + (KN_Lang == 'en' ? 'View example sentence' : '例文を見る') + '" onclick="Kantan.viewExample(\'' + word + '\'' + (drag ? ', this' : '') + ');"><i class="fa">&#xf002;</i></button>';
  }
  
  return str;
}

// parses words on /lessons/vocab-list/ pages
// EXAMPLE BELOW
/*
  Kantan.parse.vocabList({
    forceKanji : true, // forces kanji for ALL entries passed to vocab; kana is displayed as furigana
    forceKana : true, // used to force only kana (no kanji displayed)
    romaji : true, // used to display romaji (overrides kanji)
    maxMeanings : 3 // limits number of meanings shown to 3
  });
*/
Kantan.parse.vocabList = function (settings) {
  settings = settings || {};
  if (settings.limitMeanings) settings.maxMeanings = settings.limitMeanings; // port over legacy setting
  
  for (var row = document.querySelectorAll('.list-table [data-word]'), i = 0, j = row.length, kana, kanaClean, word, forceKana, forceKanji, romaji; i < j; i++) {
    kana = row[i].dataset.word;
    kanaClean = Kantan.cleanVocabKey(kana);
    word = Kantan.vocab[kana];
    forceKana = row[i].dataset.kana == 'true' || settings.forceKana ? true : false;
    forceKanji = row[i].dataset.kanji == 'true' || settings.forceKanji ? true : false;
    romaji = row[i].dataset.romaji == 'true' || settings.romaji ? true : false;
    maxMeanings = (row[i].dataset.meanings ? +row[i].dataset.meanings : undefined) || settings.maxMeanings;
    
    if (word) {
      // limits the amount of meanings shown for a word
      var meaning = word.meaning;
      if (maxMeanings != undefined) {
        for (var meaningList = meaning.split(';'), k = 0, l = maxMeanings, meaning = ''; k < l; k++) {
          if (meaningList[k]) {
            meaning += meaningList[k] + ';';
          }
        }

        // slice off last ;
        meaning = meaning.slice(0, -1); 
      }
      
      // manage additional readings
      if (word.readings) kanaClean = word.readings;
      
      // finally parse variables
      row[i].innerHTML = row[i].innerHTML
        .replace('{WORD}', (forceKanji || (!romaji && !forceKana && word.kanji && !word.often_kana) ? '<ruby>' + word.kanji + '<rt>' + kanaClean + '</rt></ruby>' : romaji && word.romaji ? '<ruby>' + kanaClean + '<rt>' + word.romaji + '</rt></ruby>' : kana))
        .replace('{BUTTONS}', '<div class="list-table-buttons">' + Kantan.create.vocabExample(kana) + Kantan.create.vocabAudio(kana, true) + '</div>')
        .replace('{MEANING}', Kantan.highlightKeywords(meaning))
        .replace('{TAGS}', '<div class="list-table-tags">' + Kantan.parse.vocabTags(kana, { excludeTextbooks : true }) + '</div>')
        .replace('{EXAMPLE}', '<div class="example">' + word.example_ja + '<br>' + word.example_en + '</div>')
        .replace('{EXAMPLE_JA}', word.example_ja)
        .replace('{EXAMPLE_EN}', word.example_en);
    }
  }
};

// cleans the vocab keys of unique identifiers
Kantan.cleanVocabKey = function (key) {
  return /-\d+$/.test(key) ? key.replace(/-\d+$/, '') : key;
};


