// LESSON 0 NUMBERS VOCAB
//
//
// # DEFINITION SYNTAX #
/* NOTE: for KANA_ONLY_WORD, if an item already exists (e.g., はい) the subsequent entries must be labeled はい-2, はい-3, etc. otherwise you will overwrite the current entry
   use Kantan.cleanVocabKey('KANA_ONLY_WORD') to clean the key for use on the website, so instead of returning はい-2, only はい will be returned

  'KANA_ONLY_WORD' : {
    kanji : 'KANJI_ONLY_WORD',
    romaji : 'ROMAJI_WORD', // only for up to Lesson 2
    meaning : 'DEFINITION',
    example_ja : 'JAPANESE_EXAMPLE_SENTENCE', // use <b class="main-color"></b> to highlight the keyword and <ruby><rt></rt></ruby> to annotate kanji with furigana
    example_en : "ENGLISH_EXAMPLE_SENTENCE",
    tag : 'PART_OF_SPEECH', // tags for the word e.g., verb, noun, expression, polite... (Kantan.vocabTagKey)
    audio : 'FILE_NAME', // pulls files from the mp3 and ogg folders in resources/audio/vocab/ using the specified file name
    often_kana : TRUE||FALSE, // true if word is usually written in kana, otherwise this property can be dropped
    common : TRUE||FALSE, // true if word is common, otherwise this property can be dropped
    lesson : LESSON_NUMBER, // lesson vocab was introduced on Kantan Japanese
    jlpt : JLPT_LEVEL,
    // lesson that the word is taught in textbooks
    genki : GENKI_LESSON,
    quartet : QUARTET_LESSON,
    tobira_b : TOBIRA_BEGINNER_LESSON,
    tobira_i : TOBIRA_INTERMEDIATE_LESSON
  }
*/

// # EMPTY DEFINITION #
/*
  '' : {
    kanji : '',
    romaji : '',
    meaning : "",
    example_ja : '<b class="main-color"></b>',
    example_en : "<b class='main-color'></b>",
    tag : '',
    audio : '',
    often_kana : true,
    common : true,
    lesson : 0,
    jlpt : 5,
    genki : 3,
    quartet : 1,
    tobira_b : 1,
    tobira_i : 1
  }
*/

// Type Key
// Preferred order: Type (A/N/V/etc) > Exp > Int > Abbr > Pol
Kantan.vocabTagKey = {
  'A' : 'い-Adjective; a descriptive word that ends with い',
  'ANa' : 'な-Adjective; a descriptive word that uses な to describe nouns',
  'ANo' : 'の-Adjective; a descriptive word that uses の to describe nouns',
  'Abbr' : 'Abbreviation; shortened form of a word or phrase',
  'Adv' : 'Adverb; a word that modifies verbs, adjectives, etc.',
  'Conj' : 'Conjunction; a word that connects words, sentences, etc. together',
  'N' : 'Noun; person, place, thing, etc.',
  'PN' : 'Pronoun; I, he, she, etc.',
  'VN' : 'Verbal Noun; a noun that can take する and act as a verb',
  'Int' : 'Interjection; a part of speech that can stand on its own',
  'Exp' : 'Expression (Phrases, clauses, etc.)',
  'Pre' : 'Prefix; a word added to the front of another word to change its meaning',
  'Suf' : 'Suffix; a word added to the end of another word to change its meaning',
  'U-Vi' : 'U-Verb (godan), Intransitive (usually takes が); does not require a direct object',
  'U-Vt' : 'U-Verb (godan), Transitive (usually takes を); requires a direct object',
  'Ru-Vi' : 'Ru-Verb (ichidan), Intransitive (usually takes が); does not require a direct object',
  'Ru-Vt' : 'Ru-Verb (ichidan), Transitive (usually takes を); requires a direct object',
  'Irr' : 'Irregular Verb (e.g., する, くる...); does not follow standard conjugation rules',
  'Pol' : 'Polite; a word or expression that is polite or formal',
  'Hum' : 'Humble; a word or phrase that lowers the speaker\'s status while showing respect to the listener',
  'Hon' : 'Honorific; a word or phrase that elevates the status of the person being spoken about'
};


